SELECT r.resource_id, r.target_scope_code, r.team_id, t.name AS team_name, r.category_code, r.title, r.status_code, r.is_pinned, MAX(rf.revision_no) AS current_revision_no, updater.name AS updated_by_name, r.updated_dttm FROM resource r LEFT JOIN team t ON t.team_id = r.team_id JOIN member updater ON updater.member_id = r.updated_by_member_id LEFT JOIN resource_file rf ON rf.resource_id = r.resource_id WHERE r.deleted_dttm IS NULL
AND (r.title LIKE CONCAT('%', #{keyword}, '%') OR r.description LIKE CONCAT('%', #{keyword}, '%'))
AND r.category_code = #{categoryCode}
AND r.status_code = #{status}
AND r.target_scope_code = #{targetScope}
AND r.team_id = #{teamId}
GROUP BY r.resource_id, r.target_scope_code, r.team_id, t.name, r.category_code, r.title, r.status_code, r.is_pinned, updater.name, r.updated_dttm ORDER BY r.updated_dttm DESC, r.resource_id DESC LIMIT #{limit} OFFSET #{offset}

