INSERT INTO resource (
    target_scope_code, team_id, category_code, title, description,
    status_code, is_pinned, created_by_member_id, updated_by_member_id
) VALUES (
    #{targetScope}, #{teamId}, #{categoryCode}, #{title}, #{description},
    #{status}, #{pinned}, #{createdByMemberId}, #{updatedByMemberId}
)

INSERT INTO resource_file (
    resource_id, stored_file_id, revision_no, display_order,
    uploaded_by_member_id
) VALUES (
    #{resourceId}, #{storedFileId}, #{revisionNo}, #{displayOrder},
    #{uploadedByMemberId}
)
